"use strict";

// Character length in Unicode code points, as ajv's `ucs2length` runtime
// helper computes it. ajv's generated validators require this module by path,
// so a validator generated by ajv keeps running after this package takes ajv's
// place.
function ucs2length(str) {
  const len = str.length;
  let length = 0;
  let pos = 0;
  let value;
  while (pos < len) {
    length++;
    value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < len) {
      value = str.charCodeAt(pos);
      if ((value & 0xfc00) === 0xdc00) pos++;
    }
  }
  return length;
}

ucs2length.code = 'require("ajv/dist/runtime/ucs2length").default';

module.exports = ucs2length;
module.exports.default = ucs2length;
